def minimum_coins_memo(coins, amount):
    coins = tuple(coins)
    memo = {0: 0}
    def solve(remaining):
        if remaining in memo:
            return memo[remaining]
        best = None
        for coin in coins:
            if coin <= remaining:
                rest = solve(remaining - coin)
                if rest is not None:
                    candidate = rest + 1
                    if best is None or candidate < best:
                        best = candidate
        memo[remaining] = best
        return best
    return solve(amount)

print(minimum_coins_memo([1, 3, 4], 6))
print(minimum_coins_memo([4], 6))
print(minimum_coins_memo([], 0))

