def once_min_coins(values, amount):
    memo = {}
    def solve(index, remaining):
        if remaining == 0:
            return 0
        if index == len(values):
            return None
        key = (index, remaining)
        if key in memo:
            return memo[key]
        best = solve(index + 1, remaining)
        if values[index] <= remaining:
            previous = solve(index + 1, remaining - values[index])
            if previous is not None:
                candidate = previous + 1
                if best is None or candidate < best:
                    best = candidate
        memo[key] = best
        return best
    return solve(0, amount)

print(once_min_coins([2], 4))
print(once_min_coins([2, 2], 4))
print(once_min_coins([3, 4], 6))
print(once_min_coins([], 0))

def memo_state_report(coins, amount):
    memo = {0: 0}
    def solve(remaining):
        if remaining in memo:
            return memo[remaining]
        best = None
        for coin in coins:
            if coin <= remaining:
                previous = solve(remaining - coin)
                if previous is not None:
                    candidate = previous + 1
                    if best is None or candidate < best:
                        best = candidate
        memo[remaining] = best
        return best
    answer = solve(amount)
    return answer, len(memo)

print(memo_state_report([2], 3))
print(memo_state_report([2], 4))
print(memo_state_report([], 0))
